:root {
  --v37-font-sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, "Noto Sans", sans-serif;
  --v37-space-xs: 8px;
  --v37-space-sm: 12px;
  --v37-space-md: 16px;
  --v37-space-lg: 24px;
  --v37-space-xl: 32px;
  --v37-radius-card: 24px;
  --v37-radius-inner: 18px;
  --v37-border: rgba(35, 47, 64, .10);
  --v37-shadow: 0 18px 45px rgba(26, 37, 56, .08);
  --v37-critical: #B42318;
  --v37-critical-bg: #FFF1F0;
  --v37-warning: #B54708;
  --v37-warning-bg: #FFF7E6;
  --v37-success: #067647;
  --v37-success-bg: #ECFDF3;
  --v37-info-bg: #EEF6FF;
}
body.v37-uat-safety-decision,
body.v37-uat-safety-decision button,
body.v37-uat-safety-decision input,
body.v37-uat-safety-decision select,
body.v37-uat-safety-decision textarea {
  font-family: var(--v37-font-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body.v37-uat-safety-decision .page {
  --page-block-gap: var(--v37-space-lg);
}
body.v37-uat-safety-decision .page > :where(section, article, div.glass, .two-col, .hero-grid, .v37-decision-cta) {
  margin-block: var(--v37-space-lg);
}
body.v37-uat-safety-decision :where(.glass, .v37-can-go, .v37-primary-decision, .v37-consent-flow, .v37-b2b-task-flow, .v37-doctor-context, .v37-uat-readiness, .v37-decision-cta) {
  border-radius: var(--v37-radius-card);
  border: 1px solid var(--v37-border);
  box-shadow: var(--v37-shadow);
}
body.v37-uat-safety-decision :where(h1, h2, h3) {
  letter-spacing: -.02em;
  line-height: 1.12;
}
body.v37-uat-safety-decision :where(p, li, dd, dt, span, small) {
  line-height: 1.45;
}
body.v37-uat-safety-decision :where(.btn, .secondary, button, .icon-btn) {
  min-height: 44px;
}
.v37-section-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--v37-space-md);
  margin-bottom: var(--v37-space-lg);
}
.v37-section-head h2 { margin: 6px 0 6px; }
.v37-section-head p { margin: 0; color: var(--muted, #667085); max-width: 820px; }
.v37-kicker,
.v37-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
  color: #475467;
}
.v37-can-go {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--v37-space-md);
  padding: var(--v37-space-lg);
}
.v37-can-go__icon {
  inline-size: 56px;
  block-size: 56px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  background: var(--v37-info-bg);
  color: #2563EB;
}
.v37-can-go__body h2 { margin: 4px 0 6px; font-size: clamp(20px, 2.4vw, 28px); }
.v37-can-go__body p { margin: 0; color: #475467; }
.v37-can-go--wait .v37-can-go__icon { background: var(--v37-warning-bg); color: var(--v37-warning); }
.v37-can-go--action .v37-can-go__icon { background: #FFF7ED; color: #C2410C; }
.v37-can-go--go { border-color: rgba(180, 35, 24, .18); background: linear-gradient(135deg, #fff, var(--v37-critical-bg)); }
.v37-can-go--go .v37-can-go__icon { background: var(--v37-critical-bg); color: var(--v37-critical); }
.v37-primary-decision,
.v37-consent-flow,
.v37-b2b-task-flow,
.v37-doctor-context,
.v37-uat-readiness,
.v37-decision-cta { padding: var(--v37-space-lg); }
.v37-decision-cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--v37-space-lg);
  background: linear-gradient(135deg, rgba(239,246,255,.9), rgba(255,255,255,.94));
}
.v37-decision-cta h2 { margin: 4px 0 6px; }
.v37-decision-cta p { margin: 0; color: #475467; }
.v37-comparison-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--v37-space-md);
}
.v37-compare-card {
  display: flex;
  flex-direction: column;
  gap: var(--v37-space-md);
  padding: 20px;
  border-radius: var(--v37-radius-inner);
  border: 1px solid var(--v37-border);
  background: #fff;
}
.v37-compare-card.is-recommended { outline: 2px solid rgba(37, 99, 235, .22); background: linear-gradient(180deg, #fff, #F8FBFF); }
.v37-compare-card.is-muted { opacity: .86; }
.v37-compare-card h3 { margin: 0; font-size: 22px; }
.v37-compare-card dl { display: grid; gap: 10px; margin: 0; }
.v37-compare-card dl div { display: grid; grid-template-columns: 82px 1fr; gap: 8px; align-items: start; }
.v37-compare-card dt { font-weight: 800; color: #344054; }
.v37-compare-card dd { margin: 0; color: #475467; }
.v37-consent-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--v37-space-md);
}
.v37-consent-steps article,
.v37-task-card,
.v37-clinical-grid article,
.v37-readiness-grid article {
  display: grid;
  gap: 10px;
  padding: 18px;
  border: 1px solid var(--v37-border);
  border-radius: var(--v37-radius-inner);
  background: #fff;
}
.v37-consent-steps article > div,
.v37-task-card > div { display: flex; gap: 10px; flex-wrap: wrap; }
.v37-consent-steps b { color: #101828; }
.v37-consent-status {
  margin-top: var(--v37-space-md);
  padding: 14px 16px;
  border-radius: 16px;
  background: var(--v37-info-bg);
  color: #1D4ED8;
  font-weight: 700;
}
.v37-task-list,
.v37-clinical-grid,
.v37-readiness-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--v37-space-md);
}
.v37-task-card.is-critical { border-color: rgba(180, 35, 24, .22); background: var(--v37-critical-bg); }
.v37-task-card.is-warning { border-color: rgba(181, 71, 8, .22); background: var(--v37-warning-bg); }
.v37-task-card span { font-weight: 800; color: #475467; }
.v37-doctor-context { background: linear-gradient(135deg, #fff, #F8FAFC); }
.v37-clinical-grid article strong,
.v37-readiness-grid article strong { font-size: 16px; }
.v37-commercial-only { transition: opacity .2s ease; }
body[data-clinic-role="doctor"] .v37-commercial-only,
body[data-clinic-role="doctor"] .v36rf-risk-kpis,
body[data-clinic-role="doctor"] .v36rf-risk-kpi { display: none !important; }
body[data-clinic-role="doctor"] .v37-doctor-context { outline: 2px solid rgba(37, 99, 235, .18); }
.bp-specification-note {
  margin-top: var(--v37-space-md);
  padding: 14px 16px;
  border-left: 4px solid #2563EB;
  border-radius: 14px;
  background: #F8FAFC;
  color: #475467;
  page-break-inside: avoid;
  break-inside: avoid;
}
@media (max-width: 1024px) {
  .v37-comparison-grid,
  .v37-consent-steps,
  .v37-task-list,
  .v37-clinical-grid,
  .v37-readiness-grid { grid-template-columns: 1fr; }
  .v37-section-head { flex-direction: column; }
}
@media (max-width: 768px) {
  body.v37-uat-safety-decision .page > :where(section, article, div.glass, .two-col, .hero-grid, .v37-decision-cta) { margin-block: var(--v37-space-md); }
  .v37-can-go { grid-template-columns: 44px 1fr; padding: 18px; }
  .v37-can-go > :where(a, button) { grid-column: 1 / -1; inline-size: 100%; }
  .v37-can-go__icon { inline-size: 44px; block-size: 44px; border-radius: 14px; }
  .v37-decision-cta { flex-direction: column; align-items: stretch; padding: 18px; }
  .v37-primary-decision,
  .v37-consent-flow,
  .v37-b2b-task-flow,
  .v37-doctor-context,
  .v37-uat-readiness { padding: 18px; }
  .v37-compare-card dl div { grid-template-columns: 1fr; gap: 2px; }
  #clinic-schedule .v36rf-resource-schedule,
  #clinic-schedule .schedule-grid,
  #clinic-schedule table { display: none !important; }
  #clinic-workspace .staff-table { display: none; }
  .v37-b2b-task-flow { display: block; }
}
@media (prefers-reduced-motion: reduce) {
  .v37-commercial-only,
  .v37-can-go,
  .v37-task-card { transition: none !important; animation: none !important; }
}
@media print {
  @page { size: A4; margin: 14mm 12mm; counter-increment: page; }
  body.v37-uat-safety-decision { background: #fff !important; }
  body.v37-uat-safety-decision .page { break-after: page; page-break-after: always; }
  body.v37-uat-safety-decision :where(.glass, .v37-can-go, .v37-primary-decision, .v37-consent-flow, .v37-b2b-task-flow) { box-shadow: none !important; break-inside: avoid; page-break-inside: avoid; }
  .bp-specification-note { page-break-inside: avoid; break-inside: avoid; }
  body.v37-uat-safety-decision::after { content: "VetHelp v37 · page " counter(page); position: fixed; right: 12mm; bottom: 7mm; color: #667085; font-size: 10px; }
}

