body.v38-simplified-navigation .subtitle{max-width:760px;}

body.v38-simplified-navigation :where(.btn,a.btn,button.primary,button.secondary,a.secondary,.secondary,button.sort-chip,.v35-filter,.v36rf-pet-toggle){
