  color:#fff!important;
  box-shadow:0 10px 22px rgba(23,103,247,.20);
}
body.v38-simplified-navigation :where(button.secondary,a.secondary,.secondary):not(.pill):not(.meta-chip):not(.trust-badge){
  border:1px solid rgba(23,103,247,.18)!important;
  background:rgba(255,255,255,.88)!important;
  color:var(--v38-blue)!important;
  box-shadow:0 8px 18px rgba(27,72,141,.08);
}
body.v38-simplified-navigation :where(.btn,button.primary,button.secondary,a.secondary,.secondary):hover{
  transform:translateY(-1px);
}
body.v38-simplified-navigation :where(.btn,button.primary,button.secondary,a.secondary,.secondary):focus-visible,
.v38-top-primary a:focus-visible,.v38-top-sos:focus-visible,.v38-top-brand:focus-visible{
