  right:auto;
  bottom:calc(10px + var(--safe-area-bottom,0px));
  width:min(760px,calc(100vw - 20px));
  height:var(--mobile-nav-h,74px);
  grid-template-columns:repeat(5,minmax(0,1fr));
  z-index:990;
  padding:7px;
