.v42-emergency-hero{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,.75fr);gap:28px;padding:30px;background:linear-gradient(135deg,rgba(255,247,247,.98),rgba(255,255,255,.92));border-color:rgba(217,45,61,.18);}
.v42-emergency-hero-copy{display:grid;align-content:center;justify-items:start;gap:14px;min-width:0;}
.v42-emergency-kicker{display:inline-flex;padding:6px 10px;border-radius:999px;background:rgba(217,45,61,.10);color:#b42332;font-size:.75rem;font-weight:900;letter-spacing:.08em;text-transform:uppercase;}
.v42-emergency-hero h2{max-width:820px;margin:0;font-size:clamp(2rem,4vw,3.45rem);line-height:1.02;letter-spacing:-.045em;color:#172036;}
