.v42-emergency-facts div{display:grid;grid-template-columns:38px minmax(0,1fr);column-gap:10px;align-items:center;padding:10px;border-radius:16px;background:#fff;}
.v42-emergency-facts div>span{grid-row:1/3;display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:rgba(217,45,61,.09);color:#b42332;font-weight:900;}
