#decision-comparison .v37-compare-card dd{margin:0;color:#243454;line-height:1.4;}
#decision-comparison .v37-compare-card>.btn,#decision-comparison .v37-compare-card>.secondary{width:100%;margin-top:auto;min-height:44px;}
