#appointment-detail>.v37-can-go>.btn{min-width:210px;max-width:100%;}
#appointment-detail>.two-col{display:grid;grid-template-columns:minmax(0,1.12fr) minmax(340px,.88fr);gap:18px;align-items:start;}
#appointment-detail>.two-col>article{min-width:0;padding:22px;}
#appointment-detail>.two-col .section-header{display:flex;flex-wrap:wrap;align-items:flex-start;gap:12px;}
#appointment-detail .stepper{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;min-width:0;}
#appointment-detail .step{min-width:0;overflow-wrap:anywhere;}
#appointment-detail .line-list{min-width:0;}
#appointment-detail .line-item{display:grid;grid-template-columns:42px minmax(0,1fr) auto;align-items:center;gap:11px;min-width:0;}
#appointment-detail .line-item>span:nth-child(2){min-width:0;}
#appointment-detail .line-item :where(strong,small){display:block;max-width:100%;}
