#appointment-detail>.section-header{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin:0;}
#appointment-detail>.doc-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;}
