:root{
  --v46-blue:#1767f7;
  --v46-ink:#16233c;
  --v46-muted:#61708a;
  --v46-line:rgba(128,161,209,.30);
  --v46-surface:rgba(252,254,255,.90);
  --v46-shadow:0 18px 44px rgba(37,78,141,.16);
}


body.v46-floating-navigation-telemed .v38-top-nav{
  position:fixed;
  top:14px;
  left:50%;
  z-index:1000;
  width:min(1120px,calc(100vw - 48px));
  min-height:64px;
  transform:translateX(-50%);
  padding:9px 12px;
  border:1px solid rgba(136,175,227,.55);
  border-radius:22px;
  background:rgba(250,253,255,.88);
  box-shadow:var(--v46-shadow);
  backdrop-filter:blur(22px) saturate(1.15);
  -webkit-backdrop-filter:blur(22px) saturate(1.15);
}
body.v46-floating-navigation-telemed .v38-top-brand{padding-inline:4px;color:var(--v46-ink);}
body.v46-floating-navigation-telemed .v38-top-brand .brand-mark{width:38px;height:38px;}
body.v46-floating-navigation-telemed .v38-top-primary{justify-content:center;gap:4px;}
body.v46-floating-navigation-telemed .v38-top-primary a{min-height:42px;padding-inline:13px;font-size:13px;}
body.v46-floating-navigation-telemed .v38-top-sos{min-height:42px;padding-inline:14px;}
body.v46-floating-navigation-telemed .main{padding-top:108px!important;}
@media(min-width:761px){body.v46-floating-navigation-telemed .tablet-compact-nav{display:none!important;}}
@media(max-width:1100px) and (min-width:701px){
  body.v46-floating-navigation-telemed .v38-top-nav{grid-template-columns:1fr auto;gap:5px 12px;}
  body.v46-floating-navigation-telemed .v38-top-primary{grid-column:1/-1;grid-row:2;justify-content:flex-start;width:100%;}
  body.v46-floating-navigation-telemed .main{padding-top:154px!important;}
}
@media(max-width:700px){
  body.v46-floating-navigation-telemed .v38-top-nav{display:none!important;}
  body.v46-floating-navigation-telemed .main{padding-top:18px!important;padding-bottom:calc(var(--mobile-nav-h,74px) + 34px)!important;}
  body.v46-floating-navigation-telemed .mobile-bottom-nav{left:10px;right:10px;bottom:calc(10px + var(--safe-area-bottom,0px));height:68px;padding:6px;background:rgba(250,253,255,.91);border-color:rgba(136,175,227,.55);border-radius:21px;box-shadow:var(--v46-shadow);}
  body.v46-floating-navigation-telemed .mobile-bottom-nav a{min-height:54px;padding:5px 2px;font-size:9px;}
}


#appointment-detail>.v37-can-go{display:none!important;}
#appointment-detail>.v46-appointment-hero{
  display:grid;
  grid-template-columns:minmax(0,1.35fr) minmax(250px,.85fr);
  gap:20px 28px;
  padding:26px;
  overflow:hidden;
  border-color:rgba(211,147,42,.28)!important;
  background:linear-gradient(120deg,rgba(255,248,232,.96),rgba(255,255,255,.92) 52%,rgba(240,247,255,.88));
