.v46-appointment-hero__main{min-width:0;}
.v46-appointment-hero .kicker{display:block;margin:9px 0 3px;color:#95611b;}
.v46-appointment-hero h2{max-width:700px;margin:0;color:var(--v46-ink);font-size:clamp(24px,3vw,38px);line-height:1.08;overflow-wrap:anywhere;}
.v46-appointment-hero p{max-width:680px;margin:10px 0 0;color:var(--v46-muted);line-height:1.5;}
