.v46-appointment-facts div{display:grid;grid-template-columns:88px minmax(0,1fr);gap:10px;padding:10px 0;border-bottom:1px solid rgba(173,139,76,.18);}
.v46-appointment-facts dt{color:var(--v46-muted);font-size:12px;font-weight:750;}
.v46-appointment-facts dd{margin:0;color:var(--v46-ink);font-weight:850;overflow-wrap:anywhere;}
.v46-appointment-actions{grid-column:1/-1;display:flex;flex-wrap:wrap;align-items:center;gap:10px;min-width:0;}
.v46-appointment-actions .section-link{padding:10px 4px;white-space:normal;}


#telemed-wait>:not(.back-link):not(.topbar):not(.v46-wait-room){display:none!important;}
#telemed-wait .v46-wait-room{display:grid;gap:16px;min-width:0;}
.v46-wait-hero{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(255px,.8fr);gap:22px;padding:26px;overflow:hidden;background:linear-gradient(130deg,rgba(235,245,255,.96),rgba(255,255,255,.93));}
