.v46-wait-payment{display:flex;align-items:flex-start;gap:10px;padding:13px 15px;border:1px solid rgba(109,157,231,.24);border-radius:16px;background:rgba(244,249,255,.74);color:var(--v46-muted);font-size:13px;line-height:1.46;}
.v46-wait-payment .vh-icon{flex:0 0 auto;width:21px;height:21px;color:var(--v46-blue);}
.v46-wait-payment strong{color:var(--v46-ink);}


#telemed-check .v46-check-doctor{display:grid;gap:16px;min-width:0;}
