.v46-check-doctor__heading h2{margin:4px 0 0;overflow-wrap:anywhere;}
.v46-check-doctor__heading .pill{flex:0 0 auto;}
.v46-check-doctor__body{display:grid;grid-template-columns:132px minmax(0,1fr);align-items:start;gap:18px;min-width:0;}
#telemed-check .v46-check-doctor .telemed-provider-photo{width:132px;min-height:160px;height:160px;margin:0;border-radius:17px;overflow:hidden;}
#telemed-check .v46-check-doctor .telemed-provider-photo img{width:100%;height:100%;object-fit:cover;object-position:center 21%;}
.v46-check-doctor__copy{min-width:0;}
.v46-check-doctor__copy>p{margin:0;overflow-wrap:anywhere;}
.v46-doctor-facts{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0;}
.v46-doctor-facts span{padding:7px 9px;border:1px solid rgba(109,157,231,.25);border-radius:10px;background:rgba(240,247,255,.72);color:#49617f;font-size:12px;font-weight:800;line-height:1.25;}
.v46-doctor-ready{display:grid;grid-template-columns:20px minmax(0,1fr);gap:8px;align-items:start;padding:11px 12px;border-radius:13px;background:rgba(232,246,239,.78);color:#355e4d;font-size:13px;line-height:1.4;}
.v46-doctor-ready .vh-icon{width:19px;height:19px;color:#168958;}
.v46-check-doctor__copy .small{margin-top:11px;line-height:1.42;}


#diary .ocr-proof-icon--scan{display:grid;place-items:center;color:var(--v46-blue);background:rgba(23,103,247,.10);}
#diary .ocr-proof-icon--scan .vh-icon{width:24px;height:24px;}


.v46-appointment-hero :where(h2,p,dd,a),.v46-wait-room :where(h2,h3,p,span,small,a),.v46-check-doctor :where(h2,p,span,small){overflow-wrap:anywhere;}
@media(max-width:860px){
