  .v46-appointment-facts div{grid-template-columns:90px minmax(0,1fr);gap:8px;padding:8px 0;}
  .v46-wait-hero__actions,.v46-appointment-actions{display:grid;grid-template-columns:1fr;}
  .v46-wait-hero__actions .btn,.v46-appointment-actions .btn,.v46-appointment-actions .section-link{width:100%;}
