  .v46-wait-doctor>img{width:76px;height:96px;border-radius:13px;}
  .v46-wait-prep{padding:16px;}
  .v46-check-doctor__body{grid-template-columns:92px minmax(0,1fr);gap:13px;}
  #telemed-check .v46-check-doctor .telemed-provider-photo{width:92px;min-height:132px;height:132px;border-radius:14px;}
  .v46-check-doctor__heading{align-items:center;}
