#diary .v47-period-switch button.is-active{background:#fff;color:var(--v47-blue);box-shadow:0 5px 14px rgba(45,85,145,.10);}
#diary .v47-health-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;min-width:0;}
#diary .v47-health-metrics>article{min-width:0;padding:15px;border:1px solid rgba(126,158,205,.25);border-radius:17px;background:rgba(255,255,255,.76);}
#diary .v47-metric-top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;min-width:0;}
#diary .v47-metric-top>span:first-child{min-width:0;}
