#diary .v47-metric-top small{color:var(--v47-muted);font-size:12px;}
#diary .v47-metric-top strong{margin-top:3px;font-size:20px;letter-spacing:-.03em;}
#diary .v47-sparkline{display:block;width:100%;height:74px;margin:11px 0 8px;overflow:visible;}
#diary .v47-chart-area{fill:rgba(23,103,247,.08);}
#diary .v47-chart-line{fill:none;stroke:#2f78ef;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;}
#diary .v47-sparkline circle{fill:#fff;stroke:#2f78ef;stroke-width:3;}
#diary .v47-metric-dates{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;}
#diary .v47-metric-dates span{min-width:0;color:var(--v47-muted);font-size:10px;line-height:1.3;overflow-wrap:anywhere;}
