#diary .v47-metric-dates span:last-child{text-align:right;}
#diary .v47-health-summary{display:grid;grid-template-columns:48px minmax(0,1fr) auto;align-items:center;gap:13px;padding:13px;border:1px solid rgba(35,157,105,.20);border-radius:15px;background:rgba(237,249,244,.72);}
#diary .v47-health-summary>img{width:48px;height:48px;object-fit:contain;mix-blend-mode:multiply;}
#diary .v47-health-summary>span{min-width:0;}
#diary .v47-health-summary :where(strong,small){display:block;overflow-wrap:anywhere;line-height:1.4;}
#diary .v47-health-summary small{margin-top:3px;color:#577067;}
#diary .v47-health-summary .btn{min-height:40px;padding:9px 13px;font-size:13px;}
