#diary .v47-diary-grid>article{min-width:0;}
#diary .v47-diary-grid .section-header{margin:0 0 12px;}
#diary .v47-diary-grid .diary-list{display:grid;gap:8px;margin:0;}
#diary .v47-diary-grid .diary-item{min-width:0;}
