.v49-clinic-client-alignment .v50-visit-progress ol { display:grid; gap:0; margin:12px 0 0; padding:0; list-style:none; }
.v49-clinic-client-alignment .v50-visit-progress li { position:relative; display:grid; grid-template-columns:28px minmax(0,1fr); gap:9px; padding:0 0 16px; }
.v49-clinic-client-alignment .v50-visit-progress li:not(:last-child)::after { content:""; position:absolute; left:13px; top:28px; bottom:0; width:2px; background:rgba(166,195,236,.58); }
.v49-clinic-client-alignment .v50-visit-progress li>span { position:relative; z-index:1; width:28px; height:28px; display:grid; place-items:center; border-radius:50%; color:#6b7b92; background:#edf3fb; font-size:11px; font-weight:900; }
.v49-clinic-client-alignment .v50-visit-progress li.is-done>span { color:#fff; background:var(--green); }
.v49-clinic-client-alignment .v50-visit-progress li.is-current>span { color:#fff; background:var(--blue); }
.v49-clinic-client-alignment .v50-visit-progress strong,
.v49-clinic-client-alignment .v50-visit-progress small { display:block; overflow-wrap:anywhere; }
.v49-clinic-client-alignment .v50-visit-progress small { margin-top:2px; color:var(--muted); font-size:10px; line-height:1.35; }

body[data-clinic-role="doctor"] .v48-admin-tabs { border-color:rgba(127,96,233,.22); }
body[data-clinic-role="doctor"] .v48-admin-tabs a.active { color:#6847bd; background:rgba(127,96,233,.10); }
body[data-clinic-role="doctor"] .v48-role-switch button.is-active { color:#6847bd; }
body[data-clinic-role="doctor"] .v48-admin-title-line .pill { color:#6847bd; border-color:rgba(127,96,233,.20); background:rgba(127,96,233,.09); }

@media(max-width:1280px){
  .v49-clinic-client-alignment .v48-visit-layout { grid-template-columns:260px minmax(0,1fr); }
}
@media(max-width:1060px){
  .v49-clinic-client-alignment .v48-telemed-layout { grid-template-columns:1fr; }
  .v49-clinic-client-alignment .v48-telemed-list { grid-template-columns:repeat(2,minmax(0,1fr)); max-height:none; }
}
@media(max-width:720px){
  .v49-clinic-client-alignment .v48-telemed-list { grid-template-columns:1fr; }
  .v49-clinic-client-alignment .v50-patient-facts>div { grid-template-columns:92px minmax(0,1fr); }
}


@media(max-width:700px){
  body.v38-simplified-navigation.v46-floating-navigation-telemed .mobile-bottom-nav{
    left:calc(8px + env(safe-area-inset-left,0px));
    right:calc(8px + env(safe-area-inset-right,0px));
    bottom:calc(8px + env(safe-area-inset-bottom,0px));
    width:auto;
    max-width:none;
    height:auto;
    min-height:68px;
    transform:none;
    box-sizing:border-box;
    grid-template-columns:repeat(5,minmax(0,1fr));
    padding:6px;
  }
  body.v38-simplified-navigation.v46-floating-navigation-telemed .mobile-bottom-nav a{
    min-width:0;
    min-height:54px;
    padding:5px 2px;
    overflow:hidden;
    font-size:9px;
    line-height:1.1;
    text-align:center;
  }
  body.v38-simplified-navigation.v46-floating-navigation-telemed .mobile-bottom-nav a :where(span,small,strong){
    max-width:100%;
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
  }
  body.v38-simplified-navigation.v46-floating-navigation-telemed .mobile-bottom-nav a .vh-icon{
    width:22px;
    height:22px;
    flex:0 0 auto;
  }
  body.v38-simplified-navigation.v46-floating-navigation-telemed .main,
  body.v38-simplified-navigation.v46-floating-navigation-telemed.admin-route .main{
    padding-bottom:calc(104px + env(safe-area-inset-bottom,0px))!important;
  }
}

@media(max-width:360px){
  body.v38-simplified-navigation.v46-floating-navigation-telemed .mobile-bottom-nav{
    left:calc(5px + env(safe-area-inset-left,0px));
    right:calc(5px + env(safe-area-inset-right,0px));
    padding-inline:4px;
  }
  body.v38-simplified-navigation.v46-floating-navigation-telemed .mobile-bottom-nav a{
    padding-inline:1px;
    font-size:8px;
  }
}


.v50-mobile-filter-disclosure,
.v50-mobile-filter-panel{
  display:contents;
}
.v50-mobile-filter-summary,
.v50-mobile-filter-actions{
  display:none;
}


@media(max-width:760px){
  #catalog .v50-mobile-filter-disclosure{
    display:block;
    width:100%;
    min-width:0;
    border:1px solid rgba(37,99,235,.16);
    border-radius:18px;
    background:rgba(248,251,255,.94);
    box-shadow:0 10px 26px rgba(37,78,141,.08);
    overflow:hidden;
  }
  #catalog .v50-mobile-filter-summary{
    display:grid;
    grid-template-columns:42px minmax(0,1fr) auto 20px;
    align-items:center;
    gap:10px;
    min-height:58px;
    padding:8px 12px;
    list-style:none;
    cursor:pointer;
    color:#17233b;
    -webkit-tap-highlight-color:transparent;
  }
  #catalog .v50-mobile-filter-summary::-webkit-details-marker{display:none;}
  #catalog .v50-mobile-filter-summary::marker{content:"";}
  #catalog .v50-mobile-filter-summary:focus-visible{
    outline:3px solid rgba(37,99,235,.24);
    outline-offset:-3px;
  }
  #catalog .v50-mobile-filter-summary__icon{
    width:42px;
    height:42px;
    display:grid;
    place-items:center;
    border-radius:13px;
    background:rgba(37,99,235,.09);
    color:#2563eb;
  }
  #catalog .v50-mobile-filter-summary__icon .vh-icon{
    width:21px;
    height:21px;
  }
  #catalog .v50-mobile-filter-summary__copy{
    min-width:0;
    display:grid;
    gap:2px;
  }
  #catalog .v50-mobile-filter-summary__copy strong{
    font-size:15px;
    line-height:1.2;
  }
  #catalog .v50-mobile-filter-summary__copy small{
    min-width:0;
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
    color:#66758d;
    font-size:11px;
    font-weight:700;
    line-height:1.25;
  }
  #catalog .v50-mobile-filter-count{
    min-width:27px;
    height:27px;
    display:grid;
    place-items:center;
    padding-inline:7px;
    border-radius:999px;
    background:#2563eb;
    color:#fff;
    font-size:12px;
    font-weight:900;
  }
  #catalog .v50-mobile-filter-chevron{
    display:grid;
    place-items:center;
    color:#65748d;
    font-size:22px;
    line-height:1;
    transform:translateY(-2px);
    transition:transform .18s ease;
  }
  #catalog .v50-mobile-filter-disclosure[open] .v50-mobile-filter-chevron{
    transform:translateY(2px) rotate(180deg);
  }
  #catalog .v50-mobile-filter-panel{
    display:grid;
    gap:12px;
    padding:0 12px 12px;
    border-top:1px solid rgba(37,99,235,.10);
  }
  #catalog .v40-filter-row.v50-mobile-filter-options{
    display:grid;
    grid-template-columns:1fr;
    gap:8px;
    width:100%;
    max-width:none;
    overflow:visible;
    padding:12px 0 0;
  }
  #catalog .v40-filter-row.v50-mobile-filter-options .filter{
    position:relative;
    width:100%;
    min-width:0;
    min-height:50px;
    justify-content:flex-start;
    gap:11px;
    padding:0 46px 0 13px;
    border-radius:14px;
    border-color:rgba(112,143,190,.25);
    background:#fff;
    box-shadow:none;
    color:#24324a;
    font-size:14px;
    text-align:left;
    white-space:normal;
  }
  #catalog .v40-filter-row.v50-mobile-filter-options .filter::after{
    content:"";
    position:absolute;
    right:14px;
    top:50%;
    width:20px;
    height:20px;
    border:2px solid #bdc9dc;
    border-radius:7px;
    transform:translateY(-50%);
    box-sizing:border-box;
  }
  #catalog .v40-filter-row.v50-mobile-filter-options .filter.active{
    border-color:rgba(37,99,235,.32);
    background:rgba(37,99,235,.08);
    color:#1d4ed8;
  }
  #catalog .v40-filter-row.v50-mobile-filter-options .filter.active::after{
    content:"✓";
    display:grid;
    place-items:center;
    border-color:#2563eb;
    background:#2563eb;
    color:#fff;
    font-size:13px;
    font-weight:900;
    line-height:1;
  }
  #catalog .v40-filter-row.v50-mobile-filter-options .chip-icon{
    width:22px;
    height:22px;
    flex:0 0 auto;
  }
  #catalog .v50-mobile-filter-actions{
    display:grid;
    grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);
    gap:8px;
  }
  #catalog .v50-mobile-filter-actions button{
    min-width:0;
    min-height:46px;
    border-radius:13px;
    padding:0 10px;
    font-size:13px;
    font-weight:850;
  }
  #catalog .v50-mobile-filter-reset{
    border:1px solid rgba(112,143,190,.28);
    background:#fff;
    color:#53627a;
  }
  #catalog .v50-mobile-filter-apply{
    border:1px solid #2563eb;
    background:linear-gradient(135deg,#2563eb,#4b8cff);
    color:#fff;
    box-shadow:0 9px 20px rgba(37,99,235,.18);
  }
}

@media(max-width:380px){
  #catalog .v50-mobile-filter-summary{
    grid-template-columns:40px minmax(0,1fr) auto 18px;
    gap:8px;
    padding-inline:10px;
  }
  #catalog .v50-mobile-filter-actions{
    grid-template-columns:1fr;
  }
}
